<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import QRCode from 'qrcode'; import { api } from '../api'; import type { Transaction } from '../types';
const route=useRoute(); const tx=ref<Transaction|null>(null); const error=ref(''); const qr=ref(''); const token=String(route.params.token)
const channelName=computed(()=>({ALIPAY:'支付宝模拟收银台',WECHAT_PAY:'微信支付模拟收银台',UNION_PAY:'银联模拟网关'}[tx.value?.channel||'']||'模拟收银台'))
onMounted(async()=>{try{const loaded=await api<Transaction>(`/api/checkout/${token}`); tx.value=loaded; if(loaded.qrPayload) qr.value=await QRCode.toDataURL(loaded.qrPayload,{width:220,margin:1})}catch(e){error.value=e instanceof Error?e.message:'交易不存在'}})
async function complete(outcome:string){try{tx.value=await api(`/api/checkout/${token}/complete?outcome=${outcome}`,{method:'POST'})}catch(e){error.value=e instanceof Error?e.message:'处理失败'}}
</script>
<template><div class="cashier-page"><div class="cashier-brand"><span class="brand-mark">M</span>MockPay <span>LOCAL ONLY</span></div><article v-if="tx" class="cashier-card"><span class="eyebrow">{{ tx.channel }}</span><h1>{{ channelName }}</h1><div class="amount"><small>应付金额</small><b>¥{{ tx.amount }}</b><span>{{ tx.currency }}</span></div><img v-if="qr" :src="qr" class="qr" alt="微信模拟支付二维码" /><dl><dt>订单</dt><dd>{{ tx.subject }}</dd><dt>渠道交易号</dt><dd class="mono">{{ tx.channelTransactionNo }}</dd><dt>状态</dt><dd><span :class="['badge',tx.status.toLowerCase()]">{{ tx.status }}</span></dd><dt>有效期</dt><dd>{{ new Date(tx.expiresAt).toLocaleString() }}</dd></dl><div v-if="tx.status==='PENDING'" class="cashier-actions"><button class="primary" @click="complete('SUCCESS')">支付成功</button><button class="secondary" @click="complete('FAILED')">普通失败</button><button class="secondary" @click="complete('INSUFFICIENT_FUNDS')">余额不足</button><button class="secondary" @click="complete('CANCELLED')">用户取消</button><button class="secondary" @click="complete('TIMEOUT')">支付超时</button></div><div v-else class="notice success">交易已进入 {{ tx.status }} 状态。本页面结果不能直接修改商城订单。</div><p class="muted small">这是本地教学收银台，不会请求真实支付机构，也不会产生资金交易。</p></article><div v-else class="cashier-card"><div v-if="error" class="notice error">{{ error }}</div><p v-else>正在读取渠道交易…</p></div></div></template>
